const LALITADITYA_INFO={id:"lalitaditya-muktapida",title:"Lalitaditya Muktapida (Karkota Emperor of Kashmir)",reignPeriod:"c. 724 – 760 CE (8th Century)",dynasty:"Karkota Dynasty of Kashmir",capital:"Parihaspore (Parihaspur) & Srinagar",monumentalLegacy:"Martand Sun Temple (Anantnag)",primaryChronicle:"Rajatarangini (River of Kings) by Kalhana (1148 CE)",quickStats:[{label:"Reign Period",value:"c. 724 – 760 CE",icon:"👑"},{label:"Dynasty",value:"Karkota Dynasty",icon:"⛰️"},{label:"Crown Temple",value:"Martand Sun Temple",icon:"☀️"},{label:"Imperial Capital",value:"Parihaspore",icon:"🏛️"},{label:"Historical Source",value:"Rajatarangini",icon:"📜"},{label:"Region",value:"Kashmir Valley",icon:"📍"}]},MARTAND_SUN_TEMPLE={title:"Martand Sun Temple (Anantnag, Kashmir)",builtYear:"c. 750 CE",architecturalStyle:"Kashmiri Classical Architecture (Greco-Roman, Gandhara, & Gupta Fusion)",deity:"Surya (The Sun God)",highlights:["Built atop a plateau (Karewa) overlooking the Kashmir Valley with 84 fluted columns.","Central sanctuary flanked by arched niches housing reliefs of Surya, Vishnu, and Ganga.","Colossal stone courtyard measuring 220 feet by 142 feet, surrounded by a colonnaded peristyle.","Blended Gandharan trefoil arches with Gupta stone carving traditions."],image:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Martand_Sun_Temple_Ruins.jpg/800px-Martand_Sun_Temple_Ruins.jpg"},CAMPAIGNS_AND_HISTORIOGRAPHY=[{title:"Tang China Alliance & Northern Diplomacy",category:"Historical Fact",detail:"Diplomatic mission sent to Tang Emperor Xuanzong in 733 CE seeking joint strategy against Tibetan Empire expansion."},{title:"Campaign against Yashovarman of Kannauj",category:"Historically Verified",detail:"Formed alliance then clashed with Yashovarman; annexed territory into Kashmir's sphere of influence."},{title:"Parihaspore Capital Foundation",category:"Archaeological Evidence",detail:"Founded the grand city of Parihaspore, constructing four grand temples for Vishnu, Buddha, and Shiva."},{title:"Trans-Himalayan Expeditions in Rajatarangini",category:"Chronicler Accounts (Kalhana)",detail:"Kalhana's 4th book of Rajatarangini describes vast marches into Central Asia, distinction drawn between historical facts and epic chronicle idealizations."}],TIMELINE_EVENTS=[{year:"c. 724 CE",title:"Accession of Lalitaditya Muktapida",description:"Succeeds Tarapida to become the 5th monarch of the Karkota dynasty of Kashmir."},{year:"733 CE",title:"Embassy to Tang Court",description:"Kashmir embassy reaches Tang imperial capital Chang'an, securing diplomatic recognition."},{year:"c. 740 CE",title:"War with Kannauj & Gangetic March",description:"Defeats King Yashovarman of Kannauj, absorbing North Indian scholars into the Kashmiri court."},{year:"c. 750 CE",title:"Consecration of Martand Sun Temple",description:"Completes the grand Martand Sun Temple and Parihaspore capital monuments."},{year:"c. 760 CE",title:"Concluding Reign & Legacy",description:"Ends legendary 36-year reign, establishing Kashmir as a Golden Age center of art and philosophy."}],REFERENCES=[{text:"Kalhana (1148). Rajatarangini: A Chronicle of the Kings of Kasmir. Trans. M. A. Stein (1900).",link:"#"},{text:"Kak, R. C. (1933). Ancient Monuments of Kashmir. India Society, London.",link:"#"},{text:"Goetz, Hermann (1969). Studies in the History and Art of Kashmir and the Indian Himalaya. Otto Harrassowitz.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={LALITADITYA_INFO:LALITADITYA_INFO,MARTAND_SUN_TEMPLE:MARTAND_SUN_TEMPLE,CAMPAIGNS_AND_HISTORIOGRAPHY:CAMPAIGNS_AND_HISTORIOGRAPHY,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});